배열인 value의 크기이다)
void BubbleSorting(int *value, int size) {
int x, y, temp;
for(x = 0; x < size; x++) {
for(y = 0; y < size - x - 1; y++) {
if( ㉠ ) {
temp = value[y];
value[y] = value[y+1];
value[y+1] = temp;
}
}
}
}

문 18. 다음 C 언어로 작성된 프로그램의 실행 결과에서 세 번째 줄에
출력되는 것은?
#include <stdio.h>
int func(int num) {
if(num == 1)
return 1;
else
return num * func(num - 1);
}
int main() {
int i;
for(i = 5; i >= 0; i--) {
if(i % 2 == 1)
printf("func(%d) : %d\n", i, func(i));
}
return 0;
}
